(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.016-t*0.28)*16 + Math.sin(x*0.02+t*0.32)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.025-t*0.4)*10 + Math.cos(sy*0.02+t*0.35)*8;
  const wy2 = Math.cos(sy*0.022+t*0.38)*9 + Math.sin(sx*0.028-t*0.42)*7;
  const sx2 = sx+wx2, sy2 = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.7],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.45+1)*50, 0.13, 1.3, 1.3],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.65+4)*40, 0.075, 2.1, 0.85]
  ];
  let aS=0, iS=0, cross=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    const a = Math.sin(d*f-t*sp);
    const inh = Math.sin(d*f*0.65+t*sp*0.55+1.5);
    aS += a*w; iS += inh*w;
    cross += a*inh*0.3;
  }
  const act=aS/7.1, inh=iS/7.1;
  const bg1 = (Math.sin(sx2*0.035+sy2*0.022+t*0.8)+Math.sin(sx2*0.028-sy2*0.038+t*1.1))/2;
  const bg2 = Math.sin((sx2+sy2)*0.11+t*2.5)*0.25+Math.sin((sx2-sy2)*0.09-t*2.1)*0.2;
  const bg3 = Math.sin(sx2*0.06+t*0.5)*Math.sin(sy2*0.07-t*0.4)*0.3;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx2-cx)**2+(sy2-cy)**2), ang=Math.atan2(sy2-cx,sx2-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.5);
  const sp2 = Math.sin(dist*0.038+ang*4.2-t*1.2);
  const sp3 = Math.sin(dist*0.06-ang*2+t*0.8)*Math.cos(dist*0.025+ang*5-t*1.8);
  const spiral = (sp1+sp2)*0.35+sp3*0.2;
  const laplacian = (Math.sin(sx2*0.12)*Math.sin(sy2*0.12)+Math.sin(sx2*0.08+sy2*0.08+t*0.7))*0.4;
  const grain = (Math.sin(sx2*1.7+t*3.1)*Math.sin(sy2*2.3-t*2.7)*Math.sin((sx2+sy2)*1.1+t*1.9))*0.04;
  const feed = 0.055+Math.sin(t*0.3)*0.015;
  const kill = 0.062+Math.cos(t*0.25)*0.012;
  const reaction = Math.tanh((act*(1+feed)-inh*(1+kill)+cross+bg*0.25+spiral+laplacian)*2.0);
  const contour = 1.0-Math.pow(Math.abs(Math.sin(reaction*Math.PI*1.5)),0.6)*0.15;
  const cell = Math.tanh((Math.sin(sx2*0.13)*Math.sin(sy2*0.13)+Math.sin((sx2+sy2)*0.09+t)*0.5)*1.8)*0.25;
  const blend = reaction*0.7+cell*0.3, v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,85],[18,85,120],[25,135,135],
    [60,175,150],[140,200,130],[210,195,75],
    [235,155,55],[220,100,60],[185,55,70],
    [130,30,65],[65,18,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18+grain;
  const edge=Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.06:1.0;
  const highlight=reaction>0.85?1.0+(reaction-0.85)*0.8:1.0;
  const m=contour*edge*highlight;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*m))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*m))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*m))|0
  ];
}
